function mattermostChannelPlan(input) {
  const text = (value, label) => { if (typeof value !== 'string' || !value.trim() || value.trim().startsWith('YOUR_')) throw new Error('Set ' + label); return value.trim(); };
  const id = (value, label) => { const result = text(value, label); if (!/^[a-z0-9]{26}$/.test(result)) throw new Error(label + ' must be a 26-character Mattermost ID'); return result; };
  const teamId = id(input.teamId, 'teamId'), userId = id(input.userId, 'userId'), channelName = text(input.channelName, 'channelName'), displayName = text(input.displayName, 'displayName'), message = text(input.message, 'message');
  return { createBody: { team_id: teamId, name: channelName, display_name: displayName, type: 'O' }, userId, message };
}

return [{json:mattermostChannelPlan({"teamId":"YOUR_MATTERMOST_TEAM_ID","userId":"YOUR_MATTERMOST_USER_ID","channelName":"docs","displayName":"Docs","message":"Hey! Welcome to the channel!"})}];

function mattermostChannelReceipt(input) {
  const succeeded = input.httpSucceeded === true || (Number.isInteger(input.statusCode) && input.statusCode >= 200 && input.statusCode < 300);
  if (!succeeded || !input.channel || typeof input.channel !== 'object' || Array.isArray(input.channel)) throw new Error('Channel creation was not confirmed. It may already have created a channel; inspect Mattermost before replaying.');
  const channel = input.channel, expected = input.createBody;
  if (typeof channel.id !== 'string' || !/^[a-z0-9]{26}$/.test(channel.id) || channel.team_id !== expected.team_id || channel.name !== expected.name || channel.display_name !== expected.display_name || channel.type !== 'O') throw new Error('Unexpected created channel. It may already exist; inspect Mattermost before replaying.');
  return { channel, channelId: channel.id, memberEndpoint: '/channels/' + encodeURIComponent(channel.id) + '/members', memberBody: { user_id: input.userId }, message: input.message };
}

const plan=$("Choose team, user and channel").first().json;return [{json:mattermostChannelReceipt({httpSucceeded:true,channel:$input.first().json,...plan})}];

function mattermostMemberReceipt(input) {
  const membership = input.membership;
  const succeeded = input.httpSucceeded === true || (Number.isInteger(input.statusCode) && input.statusCode >= 200 && input.statusCode < 300);
  if (!succeeded || !membership || typeof membership !== 'object' || Array.isArray(membership) || membership.channel_id !== input.channel.id || membership.user_id !== input.userId) throw new Error('Channel membership was not confirmed. The channel/member may already have changed; inspect Mattermost before replaying.');
  return { channel: input.channel, membership, channelId: input.channel.id, message: input.message };
}

const prior=$("Confirm the new channel").first().json;return [{json:mattermostMemberReceipt({httpSucceeded:true,membership:$input.first().json,channel:prior.channel,userId:prior.memberBody.user_id,message:prior.message})}];

function mattermostOnboardingResult(input) {
  const post = input.post;
  if (!post || typeof post !== 'object' || Array.isArray(post) || typeof post.id !== 'string' || !/^[a-z0-9]{26}$/.test(post.id) || post.channel_id !== input.channel.id || post.message !== input.message) throw new Error('Welcome post was not confirmed. The channel, membership and post may already exist; inspect Mattermost before replaying.');
  return { channel: input.channel, membership: input.membership, post, rawPost: input.rawPost };
}

const prior=$("Confirm channel membership").first().json,post=$input.first().json;return [{json:mattermostOnboardingResult({post,rawPost:post,...prior})}];
